"""This module contains the models for the key and certificate endpoints of the XUI API."""

from pydantic import BaseModel, ConfigDict, Field


# pylint: disable=too-few-public-methods
class KeysFields:
    """Stores the fields returned by the XUI API for parsing."""

    UUID = "uuid"
    AUTHS = "auths"

    ECH_SERVER_KEYS = "echServerKeys"
    ECH_CONFIG_LIST = "echConfigList"

    WEB_CERT_FILE = "webCertFile"
    WEB_KEY_FILE = "webKeyFile"


class Mldsa65KeyPair(BaseModel):
    """Represents an ML-DSA-65 key pair generated by the server.

    Attributes:
        seed (str): The seed, the private part of the key pair.
        verify (str): The verification key, the public part of the key pair.
    """

    seed: str
    verify: str


class Mlkem768KeyPair(BaseModel):
    """Represents an ML-KEM-768 key pair generated by the server.

    Attributes:
        seed (str): The seed, the private part of the key pair.
        client (str): The client key, the public part of the key pair.
    """

    seed: str
    client: str


class VlessEncryptionAuth(BaseModel):
    """Represents one VLESS encryption option generated by the server.

    Attributes:
        id (str): The ID of the option (e.g. "x25519", "mlkem768_random").
        label (str): The human-readable name of the option.
        decryption (str): The value for the inbound `decryption` setting.
        encryption (str): The value for the client `encryption` setting.
    """

    id: str
    label: str
    decryption: str = ""
    encryption: str = ""


class EchCert(BaseModel):
    """Represents an ECH (Encrypted Client Hello) key set generated by the server.

    Attributes:
        ech_server_keys (str): The server keys.
        ech_config_list (str): The config list for the clients.
    """

    ech_server_keys: str = Field(alias=KeysFields.ECH_SERVER_KEYS)  # type: ignore
    ech_config_list: str = Field(alias=KeysFields.ECH_CONFIG_LIST)  # type: ignore

    model_config = ConfigDict(populate_by_name=True)


class WebCertFiles(BaseModel):
    """Represents the paths of the web TLS certificate and key files of the panel.

    Attributes:
        web_cert_file (str): The path to the certificate file on the host of the panel.
        web_key_file (str): The path to the key file on the host of the panel.
    """

    web_cert_file: str = Field(alias=KeysFields.WEB_CERT_FILE)  # type: ignore
    web_key_file: str = Field(alias=KeysFields.WEB_KEY_FILE)  # type: ignore

    model_config = ConfigDict(populate_by_name=True)
